export IMPLEMENT_TMPDIR=<TMPDIR>
# Check the transcript for latest activity
tail -100 "$IMPLEMENT_TMPDIR/codex-impl-transcript.txt" 2>/dev/null | python3 -c "
import sys, json
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        d = json.loads(line)
        typ = d.get('type','?')
        if typ in ('message', 'assistant_message'):
            content = d.get('content', d.get('message', ''))
            if isinstance(content, list):
                for c in content:
                    if c.get('type') == 'text':
                        print(f'MSG: {c[\"text\"][:200]}')
            elif isinstance(content, str):
                print(f'MSG: {content[:200]}')
        elif typ == 'result':
            print(f'RESULT: {str(d)[:200]}')
    except:
        print(f'RAW: {line[:150]}')
" 2>/dev/null | tail -20 || tail -20 "$IMPLEMENT_TMPDIR/codex-impl-transcript.txt" 2>/dev/null | cat

